styles:
.b-gallery {
    container: b-gallery / inline-size;
    --gallery-gap: 0.75em;
}

.b-gallery__heading {
    margin: 0 0 var(--site-section-head-space, 1em);
}

/* The section's H2 type (THEMES §7.2): unset, the prose's own, and only where the prose applies
   (in the main column and under site-prose), so that nothing changes until a site sets it. */
.b-gallery__heading:where(.site-main *, .site-prose *) {
    font-family: var(--site-section-title-font, var(--site-font-heading));
    font-size: var(--site-section-title-size, var(--site-font-size-2));
    line-height: var(--site-section-title-line-height, 1.2);
    /* Unset, nothing: an inherited property falls back to the parent's. */
    text-transform: var(--site-section-title-case);
}

/* The section's rhythm (THEMES §7.2): none of its own until a site sets one, and no weight. */
:where(.b-gallery) {
    padding-block: var(--site-section-space, 0);
}

/* Up to `--gallery-columns` across, fewer when a cell would be narrower than 9em: the width of the
   column the block stands in decides, not the window. */
.b-gallery__grid {
    display: grid;
    grid-template-columns: repeat(
        auto-fill,
        minmax(min(100%, max(9em, (100% - (var(--gallery-columns, 3) - 1) * var(--gallery-gap)) / var(--gallery-columns, 3))), 1fr)
    );
    gap: var(--gallery-gap);
    margin: 0;
    padding: 0;
    list-style: none;
}

/* No margin of its own: a theme's prose spaces `li + li`, which in a grid lifts the first cell
   above its row. */
.b-gallery__cell {
    min-width: 0;
    margin: 0;
}

.b-gallery__figure {
    margin: 0;
}

.b-gallery__image {
    display: block;
    width: 100%;
    height: auto;
    border-radius: 0.25em;
}

/* The library's preview is square, and so is a cell: pictures of every shape line up. */
.b-gallery__grid .b-gallery__image {
    aspect-ratio: 1;
    object-fit: cover;
}

/* Several slides at a time line up as the grid's cells do, whatever the shape of each picture. */
.b-gallery--row .b-gallery__image {
    aspect-ratio: 4 / 3;
    object-fit: cover;
}

.b-gallery__caption {
    margin-top: 0.5em;
    font-size: 0.875em;
    opacity: 0.75;
}

/* The mosaic: the first picture of three large, the other two smaller. A narrow column puts the
   large one on top and the two side by side under it; from 36em of the block's own width the large
   one stands on the left and the two one above the other on its right. Every picture is cut to its
   cell (cover); the lightbox shows it whole. */
.b-gallery__mosaic {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--gallery-gap);
    margin: 0;
    padding: 0;
    list-style: none;
}

/* No margin of its own, as a cell of the grid: a theme's prose spaces `li + li`. */
.b-gallery__tile {
    display: flex;
    min-width: 0;
    margin: 0;
}

.b-gallery__mosaic .b-gallery__figure {
    display: flex;
    flex: 1;
    flex-direction: column;
    min-width: 0;
}

.b-gallery__shot {
    position: relative;
    flex: 1 1 auto;
    aspect-ratio: 4 / 3;
    overflow: hidden;
    border-radius: 0.25em;
}

/* The picture fills the cell whatever its shape: the cell, not the picture, sets the height. */
.b-gallery__shot > a,
.b-gallery__shot img {
    position: absolute;
    inset: 0;
    display: block;
    width: 100%;
    height: 100%;
}

.b-gallery__mosaic .b-gallery__image {
    object-fit: cover;
    border-radius: 0;
}

.b-gallery__mosaic > .b-gallery__tile:first-child,
.b-gallery__mosaic--2 > .b-gallery__tile {
    grid-column: 1 / -1;
}

@container b-gallery (min-width: 36em) {
    .b-gallery__mosaic--3 {
        grid-template-columns: 2fr 1fr;
        grid-template-rows: 1fr 1fr;
    }

    .b-gallery__mosaic--3 > .b-gallery__tile:first-child {
        grid-column: 1;
        grid-row: 1 / span 2;
    }

    /* The two small ones take the height the large one gives them, half each. */
    .b-gallery__mosaic--3 > .b-gallery__tile:not(:first-child) .b-gallery__shot {
        aspect-ratio: auto;
        min-height: 4em;
    }

    /* Fewer than three — the last group of a carousel, a short gallery — keep the height of three:
       two square halves, or one picture twice as wide as high. */
    .b-gallery__mosaic--2 > .b-gallery__tile {
        grid-column: auto;
    }

    .b-gallery__mosaic--2 .b-gallery__shot {
        aspect-ratio: 1;
    }

    .b-gallery__mosaic--1 .b-gallery__shot {
        aspect-ratio: 2;
    }
}

/* The section's head (`eyebrow`, `intro`): the heading between the line above it and the words
   under it. Without them the heading stands alone, as it always did. */
.b-gallery__head {
    margin: 0 0 var(--gallery-head-space, var(--site-section-head-space, 1em));
}

.b-gallery__head > :last-child {
    margin-bottom: 0;
}

.b-gallery__head .b-gallery__heading {
    margin: 0 0 var(--site-section-title-space, 0.5em);
}

/* In the theme's smaller size where it has one; the block has no words of a theme of its own. */
.b-gallery__eyebrow {
    margin: 0 0 var(--site-eyebrow-space, 0.5em);
    /* Unset, the parent's: font-family and line-height are inherited. */
    font-family: var(--site-eyebrow-font);
    font-size: var(--site-eyebrow-size, var(--site-font-size-6, 0.875em));
    font-weight: var(--site-eyebrow-weight, 600);
    line-height: var(--site-eyebrow-line-height);
    letter-spacing: var(--site-eyebrow-letter-spacing, 0.08em);
    text-transform: var(--site-eyebrow-case, uppercase);
}

.b-gallery__intro {
    max-width: 42rem;
    margin: 0;
    opacity: 0.75;
}

.b-gallery--center .b-gallery__head,
.b-gallery--center > .b-gallery__heading {
    text-align: center;
}

.b-gallery--center .b-gallery__intro {
    margin-inline: auto;
}

/* One under another in a narrow column (`narrow: column`), each as wide as the column. */
@container b-gallery (max-width: 35.99em) {
    .b-gallery--column .b-gallery__mosaic {
        grid-template-columns: minmax(0, 1fr);
    }
}

/* The carousel's arrows under the head (`arrows_at: head`): head, the arrows, then the pictures.
   The block's own variables are the knobs a site's theme turns: the spaces, the size, the glass. */
.b-gallery--arrows-head {
    --gallery-head-space: var(--site-space-6, 2rem);
    --gallery-arrows-space: calc(var(--site-space-6, 2rem) + var(--site-space-2, 0.5rem));
    --gallery-arrow-size: 52px;
    --gallery-glass: 64%;
    --gallery-glass-solid: 92%;
    --gallery-blur: 12px;
}

.b-gallery--arrows-head > .b-gallery__heading {
    margin-bottom: var(--gallery-head-space);
}

.b-gallery--arrows-head .webx-slider {
    gap: var(--gallery-arrows-space);
    --webx-slider-arrow-size: var(--gallery-arrow-size);
}

/* The slider names its first cell for the slides and their overlay, so `order` alone moves
   nothing: the rows are explicit, the arrows in the first and the slides under them. */
.b-gallery--arrows-head .webx-slider__controls {
    order: -1;
    grid-row: 1;
    justify-content: flex-start;
}

.b-gallery--arrows-head .webx-slider__viewport,
.b-gallery--arrows-head .webx-slider__overlay {
    grid-row: 2;
}

.b-gallery--arrows-head.b-gallery--center .webx-slider__controls {
    justify-content: center;
}

.b-gallery--arrows-head .webx-slider__button {
    border-color: color-mix(in srgb, currentColor 16%, transparent);
    background: color-mix(in srgb, var(--webx-slider-control-bg) var(--gallery-glass), transparent);
    -webkit-backdrop-filter: blur(var(--gallery-blur));
    backdrop-filter: blur(var(--gallery-blur));
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    .b-gallery--arrows-head .webx-slider__button {
        background: color-mix(in srgb, var(--webx-slider-control-bg) var(--gallery-glass-solid), transparent);
    }
}

/* The caption on the picture (`captions: over`): glass in its lower corner, small words. It lets
   a click through to the picture's link. */
.b-gallery--plates {
    --gallery-plate-inset: var(--site-space-5, 1.5rem);
    --gallery-plate-padding: var(--site-space-2, 0.5rem) var(--site-space-3, 0.75rem);
    --gallery-plate-radius: var(--site-radius-sm, 0.25em);
    --gallery-plate-glass: 72%;
    --gallery-plate-glass-solid: 92%;
    --gallery-plate-blur: 12px;
}

.b-gallery--plates .b-gallery__figure {
    position: relative;
}

.b-gallery--plates .b-gallery__caption {
    position: absolute;
    inset-inline-start: var(--gallery-plate-inset);
    bottom: var(--gallery-plate-inset);
    z-index: 1;
    max-width: calc(100% - 2 * var(--gallery-plate-inset));
    margin: 0;
    padding: var(--gallery-plate-padding);
    border-radius: var(--gallery-plate-radius);
    background: color-mix(in srgb, var(--site-color-surface, Canvas) var(--gallery-plate-glass), transparent);
    color: var(--site-color-text, CanvasText);
    font-size: 0.875em;
    line-height: 1.3;
    opacity: 1;
    pointer-events: none;
    -webkit-backdrop-filter: blur(var(--gallery-plate-blur));
    backdrop-filter: blur(var(--gallery-plate-blur));
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    .b-gallery--plates .b-gallery__caption {
        background: color-mix(in srgb, var(--site-color-surface, Canvas) var(--gallery-plate-glass-solid), transparent);
    }
}

/* The ribbon (`view: ribbon`): frames 3:4 from the column's start to the window's end, a strip
   that scrolls sideways — a finger, the wheel, the keyboard; no script. The section spans the page
   (`site-bleed`) and keeps its start to the column; anywhere but the main column it is the
   column it stands in. */
.b-gallery--ribbon {
    --gallery-ribbon-start: 0px;
    --gallery-ribbon-column: 100cqi;
}

.b-gallery--ribbon:where(.site-main > *) {
    --gallery-ribbon-column: min(
        100cqi - 2 * var(--site-section-gutter, var(--site-gutter)),
        var(--site-container-width) - 2 * var(--site-section-gutter, var(--site-gutter))
    );
    --gallery-ribbon-start: calc((100cqi - var(--gallery-ribbon-column)) / 2);
}

.b-gallery--ribbon .b-gallery__head {
    padding-inline: var(--gallery-ribbon-start);
}

.b-gallery__ribbon {
    /* How many frames the column holds: a part of the last one shows, there is more to the side. */
    --gallery-ribbon-across: 4.25;
    display: flex;
    gap: var(--gallery-gap);
    margin: 0;
    padding: 0 var(--gallery-ribbon-start);
    padding-inline-end: 0;
    list-style: none;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scroll-padding-inline: var(--gallery-ribbon-start);
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
}

.b-gallery__ribbon::-webkit-scrollbar {
    display: none;
}

.b-gallery__ribbon:focus-visible {
    outline: 2px solid currentColor;
    outline-offset: 2px;
}

.b-gallery__frame {
    position: relative;
    flex: 0 0 calc((var(--gallery-ribbon-column) - (var(--gallery-ribbon-across) - 1) * var(--gallery-gap)) / var(--gallery-ribbon-across));
    min-width: 0;
    margin: 0;
    scroll-snap-align: start;
}

/* The end of the strip keeps a gutter after its last frame. */
.b-gallery__frame:last-child {
    margin-inline-end: var(--gallery-ribbon-start);
}

/* The section is the container: what a query sets stands on the strip inside it. */
@container b-gallery (max-width: 39.99em) {
    .b-gallery__ribbon {
        --gallery-ribbon-across: 1.5;
    }
}

@container b-gallery (min-width: 40em) and (max-width: 63.99em) {
    .b-gallery__ribbon {
        --gallery-ribbon-across: 2.5;
    }
}

.b-gallery__post {
    display: block;
    position: relative;
    overflow: hidden;
    border-radius: 0.25em;
    color: inherit;
}

.b-gallery__post:focus-visible {
    outline: 2px solid currentColor;
    outline-offset: 2px;
}

.b-gallery__ribbon .b-gallery__image {
    aspect-ratio: 3 / 4;
    object-fit: cover;
    border-radius: 0;
}

/* What the post is — pinned, a video — in its upper corner, on the same glass as a caption. */
.b-gallery__badge {
    position: absolute;
    top: var(--site-space-3, 0.75rem);
    inset-inline-end: var(--site-space-3, 0.75rem);
    display: inline-flex;
    padding: var(--site-space-1, 0.25rem);
    border-radius: var(--site-radius-full, 9999px);
    background: color-mix(in srgb, var(--site-color-surface, Canvas) 72%, transparent);
    color: var(--site-color-text, CanvasText);
    pointer-events: none;
    -webkit-backdrop-filter: blur(12px);
    backdrop-filter: blur(12px);
}

